const items = $input.all();

return items.map(item => {
  const data = item.json || {};
  let response = data.text ?? data.output ?? data.response ?? data.message?.content ?? data.data;

  if (!response) {
    throw new Error("البيانات مش واصلة من نود الـ AI. تأكد إن نود الـ AI شغالة ومرجعتش نتيجة فارغة.");
  }

  if (typeof response === "string") {
    response = response.replace(/```json/gi, "").replace(/```/g, "").trim();
  }

  const student = typeof response === "object" ? response : JSON.parse(response);
  const rawStatus = String(student.student_status ?? student.status ?? "").toLowerCase().trim();

  let normalizedStatus;
  if (/\bfailed\b|\bdid not pass\b|\bnot passed\b/.test(rawStatus)) {
    normalizedStatus = "Failed";
  } else if (/\bpassed\b/.test(rawStatus)) {
    normalizedStatus = "Passed";
  } else {
    normalizedStatus = "Failed"; // قيمة افتراضية عشان الكود ما يضربش لو الحالة مش واضحة
  }

  return {
    json: {
      student_name: student.student_name ?? student.name ?? "Student",
      student_email: student.student_email ?? student.email ?? null,
      student_status: normalizedStatus,
      is_passed: normalizedStatus === "Passed" ? "true" : "false",
      additional_info: student.additional_info ?? student.feedback ?? "No details provided"
    }
  };
});
